textwrap.dedent('
            from mcp.server.fastmcp import FastMCP

            mcp = FastMCP("Row-Bot Test MCP")


            @mcp.tool()
            def echo(message: str) -> str:
                return f"echo:{message}"


            if __name__ == "__main__":
                mcp.run("stdio")
        ').strip

call_source:
textwrap.dedent('
            from mcp.server.fastmcp import FastMCP

            mcp = FastMCP("Row-Bot Test MCP")


            @mcp.tool()
            def echo(message: str) -> str:
                return f"echo:{message}"


            if __name__ == "__main__":
                mcp.run("stdio")
        ').strip()

